mapper.select:
SELECT c.* FROM community_member m JOIN community c ON c.id = m.community_id
WHERE m.user_id = #{userId} AND c.status = 'ACTIVE'
AND c.id < #{before}
ORDER BY c.id DESC LIMIT #{size}

mapper.update:
UPDATE community
SET status = 'ARCHIVED',
    visibility = 'PRIVATE',
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{id}
  AND owner_id = #{ownerId}
  AND status = 'ACTIVE'
  AND version = #{expectedVersion}
